import fs from 'fs';
const lines = fs.readFileSync('C:/Users/Administrator/Downloads/session.v4.jsonl','utf8').split(/\n/).filter(Boolean);
const usage = [];
const calls = [];
const results = [];
for (const line of lines) {
  const o = JSON.parse(line);
  if (o.type === 'assistant/message') {
    const u = o.data?.usage || null;
    usage.push({ turn: o.data.turn, step: o.data.step, u });
  }
  if (o.type === 'tool/call') {
    const m = o.data?.message || {};
    const blocks = m.content || o.data?.content || [];
    const tc = Array.isArray(blocks) ? blocks.filter(b => b.type === 'tool-call' || b.type === 'tool_use') : [];
    if (tc.length) {
      for (const b of tc) calls.push({ turn: o.data.turn, step: o.data.step, name: b.name, args: b.arguments || b.input });
    } else if (m.name) {
      calls.push({ turn: o.data.turn, step: o.data.step, name: m.name, args: m.arguments });
    } else {
      calls.push({ turn: o.data.turn, step: o.data.step, name: 'UNKNOWN', keys: Object.keys(o.data||{}) });
    }
  }
  if (o.type === 'tool/result') {
    const msg = o.data?.message || {};
    const text = (msg.content || []).map(c => c.text || '').join(' ').slice(0, 240);
    results.push({ turn: o.data.turn, step: o.data.step, isError: !!msg.isError, text });
  }
}
const buckets = { missing: 0, allZero: 0, real: 0 };
let sum = { in: 0, out: 0, cr: 0, tot: 0 };
for (const x of usage) {
  if (!x.u) buckets.missing++;
  else if (!(x.u.inputTokens || x.u.outputTokens || x.u.cacheReadTokens || x.u.totalTokens)) buckets.allZero++;
  else {
    buckets.real++;
    sum.in += x.u.inputTokens||0; sum.out += x.u.outputTokens||0; sum.cr += x.u.cacheReadTokens||0; sum.tot += x.u.totalTokens||0;
    console.log('REAL', x.turn+':'+x.step, JSON.stringify(x.u));
  }
}
console.log('BUCKETS', buckets, 'SUM', sum, 'assistant', usage.length, 'calls', calls.length);
const by = {};
for (const c of calls) by[c.name] = (by[c.name]||0)+1;
console.log('TOOLS', by);
const bad = results.filter(r => r.isError || /ParserError|No columns|INVALID_ARGUMENT|unknown server|CONNECTION_NOT_FOUND|\u65e0\u6548\u7684/i.test(r.text));
console.log('BAD', bad.length);
for (const b of bad) console.log(b.turn+':'+b.step, b.isError, b.text.replace(/\s+/g,' ').slice(0,180));
console.log('--- read/grep ---');
for (const c of calls.filter(c => c.name==='read' || c.name==='grep' || c.name==='pwsh')) {
  let a = {};
  try { a = typeof c.args === 'string' ? JSON.parse(c.args) : (c.args||{}); } catch {}
  const fp = String(a.file_path||a.path||a.command||'').replace(/.*[\\/]/,'').slice(0,80);
  console.log(c.turn+':'+c.step, c.name, fp, a.offset??'', a.limit??'', String(a.pattern||'').slice(0,50));
}

